window.GCAM_DIAGRAMS = {"hero": {"title": "The GCAM system", "caption": "People, energy, land and water trade through one marketplace every five years; emissions go to the Hector climate model. Choose a depth, then select a box.", "nodes": [{"id": "soc", "label": "People and economy", "sub": "population, GDP", "x": 130, "y": 80, "w": 200, "h": 64, "sys": "economy", "detail": {"1": "How many people, and how rich. More people and higher incomes mean more demand for energy, food and water.", "2": "Population and labour productivity per region come from the Shared Socioeconomic Pathways; GDP drives every demand through income elasticities. GCAM 9.0 added the KLEAM macro module.", "3": "Research angle: income and wage growth set the value of travel time, so they shift transport mode choice. Test faster and slower GDP paths as a sensitivity."}}, {"id": "en", "label": "Energy", "sub": "resources, power, fuels, demand", "x": 450, "y": 80, "w": 200, "h": 64, "sys": "energy", "detail": {"1": "Coal, oil, gas, sun, wind and biomass become electricity and fuels that homes, factories and vehicles use.", "2": "Graded resource supply curves; electricity with a value-factor adjustment for wind and solar; refining, hydrogen; buildings, industry and transport demands. Technologies compete by nested logit.", "3": "Research angle: transport sits here, as passenger and freight sectors nested by mode, size class and technology, with costs from OTAQ_trn_data_EMF37.csv and absolute-cost logits inside modes."}}, {"id": "mk", "label": "Marketplace", "sub": "prices clear every market", "x": 450, "y": 250, "w": 200, "h": 64, "sys": "neutral", "detail": {"1": "Every good has a price. The model keeps adjusting prices until what is supplied equals what is wanted.", "2": "Recursive-dynamic partial equilibrium: in each 5-year period the solver (Broyden's method) adjusts all prices until excess demand is below tolerance in every market. No foresight.", "3": "Research angle: check the solver log for unsolved markets before you trust a run; constraints (caps) add markets whose prices are shadow prices."}}, {"id": "land", "label": "Land and food", "sub": "crops, forests, bioenergy", "x": 130, "y": 250, "w": 200, "h": 64, "sys": "land", "detail": {"1": "Land is shared between crops, animals, forests and energy crops, depending on what earns the most.", "2": "More than 300 land units; nested logit on expected profit per hectare; yields, land carbon, and a land-carbon price when carbon is priced.", "3": "Research angle: biofuels for aviation and shipping pull on this land; trace the land and food-price side effects of transport policy."}}, {"id": "wat", "label": "Water", "sub": "235 basins", "x": 130, "y": 420, "w": 200, "h": 64, "sys": "water", "detail": {"1": "Farms, power plants, factories and towns all need water; each river basin has only so much.", "2": "Withdrawals and consumption by sector in 235 basins; supply from renewable water, then groundwater, then desalination, with a basin water price.", "3": "Research angle: electrifying transport raises power demand, and power plants need cooling water in water-stressed basins."}}, {"id": "em", "label": "Emissions", "sub": "CO2 and other gases", "x": 450, "y": 420, "w": 200, "h": 64, "sys": "climate", "detail": {"1": "Burning fuel, clearing land and some industries release CO2 and other gases.", "2": "Emissions are activity × emission factor, with marginal abatement cost curves for non-CO2 gases and land-use change emissions from the land model.", "3": "Research angle: tailpipe CO2 vs upstream emissions in power and hydrogen; report both, and decompose changes into activity, structure, intensity and carbon."}}, {"id": "cl", "label": "Climate (Hector)", "sub": "concentrations, warming", "x": 770, "y": 420, "w": 200, "h": 64, "sys": "climate", "detail": {"1": "Emissions add up in the air and warm the planet.", "2": "Hector, a simple climate model run inside GCAM each period, turns emissions into concentrations, radiative forcing and temperature.", "3": "Research angle: climate targets can be imposed as constraints; for uncertainty, pair GCAM with an emulator such as FaIR or MAGICC."}}, {"id": "pol", "label": "Policy", "sub": "carbon price, limits, standards", "x": 770, "y": 165, "w": 200, "h": 64, "sys": "policy", "detail": {"1": "A policy changes the rules: a price on carbon, a limit on emissions, or a standard on technologies.", "2": "Carbon prices (in 1990$ per tonne of carbon), emissions constraints solved as markets, climate targets, and portfolio standards built as credit markets.", "3": "Research angle: a zero-emission-vehicle standard can be built as a credit market in add-on XML; test it against a carbon price that gives the same emissions."}}], "edges": [{"from": "soc", "to": "en", "label": "energy demand"}, {"from": "soc", "to": "land", "label": "food demand"}, {"from": "en", "to": "mk", "label": "supply, demand"}, {"from": "land", "to": "mk", "label": "crops, biomass"}, {"from": "mk", "to": "en", "label": "prices", "sys": "neutral"}, {"from": "wat", "to": "land", "label": "irrigation"}, {"from": "en", "to": "em", "label": "fuel CO2"}, {"from": "land", "to": "em", "label": "land-use CO2"}, {"from": "em", "to": "cl", "label": "emissions"}, {"from": "pol", "to": "mk", "label": "carbon price"}, {"from": "wat", "to": "em", "sys": "water", "label": "cooling water"}], "tour": [{"focus": ["soc"], "text": "Start with people: how many, and how rich. These come from the Shared Socioeconomic Pathways."}, {"focus": ["soc", "en", "land"], "edges": [["soc", "en"], ["soc", "land"]], "text": "People need energy services and food, so demand flows into the energy system and onto the land."}, {"focus": ["en", "land", "mk"], "edges": [["en", "mk"], ["land", "mk"], ["mk", "en"]], "text": "Every good is traded in a market. The solver moves prices until supply meets demand everywhere at once."}, {"focus": ["wat", "land", "em"], "edges": [["wat", "land"], ["wat", "em"]], "text": "Water links farms and power plants: irrigation and cooling compete for each basin's supply."}, {"focus": ["en", "land", "em", "cl"], "edges": [["en", "em"], ["land", "em"], ["em", "cl"]], "text": "Activities release emissions, and Hector turns them into warming."}, {"focus": ["pol", "mk"], "edges": [["pol", "mk"]], "text": "A policy changes prices. Run the same world with and without it: the difference is the policy's effect."}]}, "m1.1": {"title": "The IAM machine", "caption": "Notice that policies are an input you choose, and temperature is an output. Every box must agree with every other box.", "nodes": [{"id": "inputs", "label": "Inputs you choose", "sub": "people, income, costs, policies", "x": 120, "y": 260, "w": 190, "h": 110, "sys": "neutral", "detail": "<b>Assumptions, not facts.</b> Population, income per person, technology costs, resources and policies. Change an input and you get a different, equally consistent future."}, {"id": "economy", "label": "Economy", "sub": "how much is demanded", "x": 400, "y": 80, "w": 170, "h": 64, "sys": "economy", "detail": "Population and income set how much energy, food and materials people want. More income usually means more demand."}, {"id": "energy", "label": "Energy", "sub": "how it is supplied", "x": 400, "y": 200, "w": 170, "h": 64, "sys": "energy", "detail": "Coal, gas, oil, solar, wind, nuclear and bioenergy compete to meet demand. Cheaper options win bigger shares."}, {"id": "land", "label": "Land and water", "sub": "food, forests, bioenergy", "x": 400, "y": 330, "w": 170, "h": 64, "sys": "land", "detail": "Cropland, pasture and forests compete for land; farms, power plants and cities compete for water."}, {"id": "emissions", "label": "Emissions", "sub": "counted from activity", "x": 620, "y": 265, "w": 150, "h": 64, "sys": "climate", "detail": "CO<sub>2</sub> and other gases are counted from the fuels burned and the land cleared. Nothing is guessed separately."}, {"id": "climate", "label": "Climate", "sub": "emissions to warming", "x": 620, "y": 430, "w": 150, "h": 64, "sys": "climate", "detail": "A simple climate model turns emissions into concentrations, extra heat-trapping (forcing) and temperature."}, {"id": "outputs", "label": "Outputs: what-if results", "sub": "energy mix, prices, emissions, °C", "x": 800, "y": 120, "w": 170, "h": 110, "sys": "data", "detail": "<b>Projections, not predictions.</b> Each output is only as good as the assumptions you fed in."}, {"id": "policy", "label": "Policies", "sub": "carbon price, targets", "x": 120, "y": 440, "w": 170, "h": 64, "sys": "policy", "detail": "Policies are inputs too: a carbon price, an emissions limit or a technology standard. The model works out what follows."}], "edges": [{"from": "inputs", "to": "economy", "label": "drivers", "sys": "economy"}, {"from": "inputs", "to": "energy", "label": "costs", "sys": "energy"}, {"from": "economy", "to": "energy", "label": "demand", "sys": "economy"}, {"from": "economy", "to": "land", "label": "food demand", "sys": "economy"}, {"from": "land", "to": "energy", "label": "bioenergy", "sys": "land"}, {"from": "energy", "to": "emissions", "label": "fuel burned", "sys": "energy"}, {"from": "land", "to": "emissions", "label": "land-use CO2", "sys": "land"}, {"from": "emissions", "to": "climate", "label": "gases", "sys": "climate"}, {"from": "energy", "to": "outputs", "label": "energy mix", "sys": "energy"}, {"from": "climate", "to": "outputs", "label": "warming", "sys": "climate"}, {"from": "policy", "to": "energy", "label": "rules and prices", "sys": "policy"}], "tour": [{"focus": ["inputs", "policy"], "edges": [], "text": "Start on the left: you choose the inputs, including the policies. They are assumptions, not facts."}, {"focus": ["economy"], "edges": [["inputs", "economy"]], "text": "People and income set how much energy, food and materials are wanted."}, {"focus": ["energy", "land"], "edges": [["economy", "energy"], ["economy", "land"], ["land", "energy"]], "text": "Energy and land systems meet that demand. They are linked: bioenergy needs land."}, {"focus": ["emissions"], "edges": [["energy", "emissions"], ["land", "emissions"]], "text": "Emissions are counted from what is burned and cleared, so they always match the activity."}, {"focus": ["climate"], "edges": [["emissions", "climate"]], "text": "A simple climate model turns the emissions into warming."}, {"focus": ["outputs"], "edges": [["energy", "outputs"], ["climate", "outputs"]], "text": "Out come consistent what-if results. Change one input and every box changes with it."}]}, "m1.2": {"title": "The climate chain inside every IAM", "caption": "Notice that each link hands its result to the next. An IAM computes the first link and passes it to a simple climate model for the rest.", "nodes": [{"id": "act", "label": "Human activity", "sub": "fuel burned, land cleared", "x": 110, "y": 110, "w": 170, "h": 70, "sys": "energy", "detail": "Power plants, cars, factories and land clearing. In an IAM this is what the energy and land parts calculate."}, {"id": "emis", "label": "Emissions", "sub": "Gt CO2 per year (the tap)", "x": 330, "y": 110, "w": 170, "h": 70, "sys": "climate", "detail": "About 40 Gt of CO<sub>2</sub> a year today (approximate). Gt means billion tonnes."}, {"id": "conc", "label": "Concentration", "sub": "ppm of CO2 in the air", "x": 560, "y": 110, "w": 170, "h": 70, "sys": "climate", "detail": "About 280 ppm before industry, about 420 ppm today. CO<sub>2</sub> stays in the air for centuries, so it piles up."}, {"id": "forc", "label": "Forcing", "sub": "extra heat trapped, W/m²", "x": 780, "y": 110, "w": 170, "h": 70, "sys": "climate", "detail": "Watts per square metre of extra heat held in. Scenario labels such as SSP2-4.5 name the forcing in 2100: 4.5 W/m²."}, {"id": "temp", "label": "Temperature", "sub": "°C above pre-industrial", "x": 780, "y": 300, "w": 170, "h": 70, "sys": "climate", "detail": "About 1.1 °C of warming around 2020. Rule of thumb: about 0.45 °C more per 1,000 Gt of CO<sub>2</sub> emitted."}, {"id": "budget", "label": "Carbon budget", "sub": "the rim of the bathtub", "x": 500, "y": 300, "w": 190, "h": 70, "sys": "policy", "detail": "From the start of 2020: about 500 Gt for a 50% chance of 1.5 °C, about 1,150 Gt for a 67% chance of 2 °C (IPCC AR6 WGI)."}, {"id": "impacts", "label": "Impacts", "sub": "heat, rain, sea level", "x": 780, "y": 450, "w": 170, "h": 64, "sys": "neutral", "detail": "Most IAMs stop at temperature. Cost-benefit models add a damage function that turns warming into lost output."}, {"id": "hector", "label": "Simple climate model", "sub": "Hector inside GCAM", "x": 330, "y": 430, "w": 190, "h": 70, "sys": "data", "detail": "GCAM hands its emissions to Hector, a simple climate model, which computes concentrations, forcing and temperature."}], "edges": [{"from": "act", "to": "emis", "label": "releases", "sys": "energy"}, {"from": "emis", "to": "conc", "label": "accumulates", "sys": "climate"}, {"from": "conc", "to": "forc", "label": "traps heat", "sys": "climate"}, {"from": "forc", "to": "temp", "label": "warms", "sys": "climate"}, {"from": "temp", "to": "impacts", "label": "causes", "sys": "climate"}, {"from": "emis", "to": "budget", "label": "running total", "sys": "policy"}, {"from": "budget", "to": "temp", "label": "0.45 °C per 1,000 Gt", "sys": "policy"}, {"from": "emis", "to": "hector", "label": "handed over", "sys": "data"}], "tour": [{"focus": ["act", "emis"], "edges": [["act", "emis"]], "text": "Burning fuel and clearing land release CO2: the tap of the bathtub, about 40 Gt a year."}, {"focus": ["conc"], "edges": [["emis", "conc"]], "text": "CO2 stays for centuries, so it piles up: from about 280 ppm before industry to about 420 ppm today."}, {"focus": ["forc", "temp"], "edges": [["conc", "forc"], ["forc", "temp"]], "text": "More CO2 traps more heat (forcing), and the extra heat warms the planet."}, {"focus": ["budget"], "edges": [["emis", "budget"], ["budget", "temp"]], "text": "Because CO2 piles up, warming follows the running total: about 0.45 °C per 1,000 Gt. The budget is the room left under the rim."}, {"focus": ["hector"], "edges": [["emis", "hector"]], "text": "Inside GCAM, the emissions are handed to Hector, a simple climate model that does the last three links."}, {"focus": ["impacts"], "edges": [["temp", "impacts"]], "text": "Impacts come last. Most process-based IAMs stop at temperature; cost-benefit models add damages."}]}, "m1.3": {"title": "From the mine to your phone, and the four Kaya factors", "caption": "Notice that losses happen at every step of the chain, and that the four Kaya factors multiply into CO2.", "nodes": [{"id": "primary", "label": "Primary energy", "sub": "coal, oil, gas, sun, wind", "x": 110, "y": 90, "w": 180, "h": 70, "sys": "energy", "detail": "Energy as nature provides it. Illustrative chain: start with 100 units of coal."}, {"id": "convert", "label": "Conversion", "sub": "power plants, refineries", "x": 340, "y": 90, "w": 170, "h": 70, "sys": "energy", "detail": "A 40%-efficient power plant turns 100 units of coal into 40 units of electricity (illustrative)."}, {"id": "final", "label": "Final energy", "sub": "electricity, petrol, heat", "x": 560, "y": 90, "w": 170, "h": 70, "sys": "energy", "detail": "What reaches homes and factories. The grid loses about 10%, so 40 becomes 36 (illustrative)."}, {"id": "service", "label": "Energy services", "sub": "light, warmth, travel, steel", "x": 780, "y": 90, "w": 170, "h": 70, "sys": "economy", "detail": "What people actually want. IAMs start from demand for services and work backwards to fuels."}, {"id": "pop", "label": "People", "sub": "population", "x": 110, "y": 330, "w": 150, "h": 64, "sys": "economy", "detail": "Factor 1 of the Kaya identity: how many people."}, {"id": "inc", "label": "Income per person", "sub": "GDP ÷ people", "x": 310, "y": 330, "w": 160, "h": 64, "sys": "economy", "detail": "Factor 2: how rich they are. Richer people usually want more services."}, {"id": "eint", "label": "Energy per $", "sub": "energy ÷ GDP", "x": 520, "y": 330, "w": 160, "h": 64, "sys": "energy", "detail": "Factor 3: how much energy each dollar of output needs. Efficiency lowers it."}, {"id": "cint", "label": "CO2 per energy", "sub": "CO2 ÷ energy", "x": 730, "y": 330, "w": 160, "h": 64, "sys": "energy", "detail": "Factor 4: how dirty the energy is. Solar, wind and nuclear lower it."}, {"id": "co2", "label": "CO2 emissions", "sub": "the four factors multiplied", "x": 450, "y": 460, "w": 220, "h": 64, "sys": "climate", "detail": "CO<sub>2</sub> = people × (GDP ÷ people) × (energy ÷ GDP) × (CO<sub>2</sub> ÷ energy). The terms cancel, so it is always true."}], "edges": [{"from": "primary", "to": "convert", "label": "100 units", "sys": "energy"}, {"from": "convert", "to": "final", "label": "40 units", "sys": "energy"}, {"from": "final", "to": "service", "label": "36 units", "sys": "energy"}, {"from": "pop", "to": "co2", "label": "×", "sys": "economy"}, {"from": "inc", "to": "co2", "label": "×", "sys": "economy"}, {"from": "eint", "to": "co2", "label": "×", "sys": "energy"}, {"from": "cint", "to": "co2", "label": "×", "sys": "energy"}], "tour": [{"focus": ["service"], "edges": [], "text": "Start at the end: people want services such as light, warmth and travel, not energy itself."}, {"focus": ["primary", "convert"], "edges": [["primary", "convert"]], "text": "Energy starts as primary energy. A power plant that is 40% efficient turns 100 units of coal into 40 of electricity."}, {"focus": ["final"], "edges": [["convert", "final"], ["final", "service"]], "text": "The grid loses about 10%, so 36 units reach homes. Saving 1 unit at home saves about 2.8 at the mine."}, {"focus": ["pop", "inc"], "edges": [["pop", "co2"], ["inc", "co2"]], "text": "Now the Kaya identity. The first two factors are about society: how many people and how rich."}, {"focus": ["eint", "cint"], "edges": [["eint", "co2"], ["cint", "co2"]], "text": "The last two are about technology: energy per dollar and CO2 per unit of energy. IAMs spend most of their detail here."}, {"focus": ["co2"], "edges": [], "text": "The four factors multiply into CO2. Change them by percentages and you must multiply the ratios, not add the percentages."}]}, "m1.4": {"title": "How prices drive choices in an IAM", "caption": "Notice the loop: costs set prices, prices set shares, shares set emissions, and a carbon price feeds emissions back into costs.", "nodes": [{"id": "demand", "label": "Demand", "sub": "what buyers want", "x": 110, "y": 110, "w": 160, "h": 64, "sys": "economy", "detail": "Buyers want less when the price is high. Toy lab numbers: demand = 1000 − 4 × price."}, {"id": "supply", "label": "Supply", "sub": "what sellers offer", "x": 110, "y": 300, "w": 160, "h": 64, "sys": "energy", "detail": "Sellers offer more when the price is high. Toy numbers: supply = 6 × price."}, {"id": "price", "label": "Market price", "sub": "moves until they match", "x": 350, "y": 205, "w": 180, "h": 70, "sys": "economy", "detail": "Equilibrium: 1000 − 4p = 6p, so p = 100 and quantity = 600 (illustrative)."}, {"id": "costs", "label": "Technology costs", "sub": "coal 60, gas 70, solar 80", "x": 600, "y": 90, "w": 190, "h": 70, "sys": "energy", "detail": "Illustrative costs in $ per MWh before any carbon price."}, {"id": "carbon", "label": "Carbon price", "sub": "$ per tonne CO2", "x": 600, "y": 330, "w": 170, "h": 64, "sys": "policy", "detail": "New cost = start cost + emission factor × carbon price. At $50: coal 105, gas 90, solar 80."}, {"id": "shares", "label": "Market shares", "sub": "cheaper gets more", "x": 810, "y": 205, "w": 150, "h": 70, "sys": "energy", "detail": "GCAM does not give everything to the cheapest option. It shares the market by relative cost (a logit choice, Go 2)."}, {"id": "future", "label": "Discounting", "sub": "future counts less", "x": 350, "y": 440, "w": 180, "h": 64, "sys": "economy", "detail": "Value today = future amount ÷ (1 + rate)^years. $100 in 100 years: $22.56 at 1.5%, $5.20 at 3%, $0.76 at 5%."}], "edges": [{"from": "demand", "to": "price", "label": "pulls up", "sys": "economy"}, {"from": "supply", "to": "price", "label": "pushes down", "sys": "energy"}, {"from": "costs", "to": "shares", "label": "relative cost", "sys": "energy"}, {"from": "carbon", "to": "costs", "label": "adds ef × price", "sys": "policy"}, {"from": "price", "to": "costs", "label": "fuel prices", "sys": "economy"}, {"from": "future", "to": "carbon", "label": "weighs damages", "sys": "economy"}], "tour": [{"focus": ["demand", "supply"], "edges": [], "text": "Idea one: buyers want less when prices are high; sellers offer more."}, {"focus": ["price"], "edges": [["demand", "price"], ["supply", "price"]], "text": "The price moves until they match: the equilibrium. In the toy market, price 100 and quantity 600."}, {"focus": ["carbon", "costs"], "edges": [["carbon", "costs"]], "text": "Idea two: a carbon price adds emissions × price to each option's cost. Coal is hit hardest, solar not at all."}, {"focus": ["shares"], "edges": [["costs", "shares"]], "text": "Cheaper options win bigger shares. Real models share the market rather than pick a single winner."}, {"focus": ["future"], "edges": [["future", "carbon"]], "text": "Idea three: discounting. The rate decides how much future damage counts today, and so how strong a policy looks worthwhile."}]}, "m1.5": {"title": "Two labels make a scenario", "caption": "Notice that the SSP story and the forcing level are chosen separately, and the IAM works out the energy and land system that joins them.", "nodes": [{"id": "ssp", "label": "SSP story", "sub": "how society develops", "x": 120, "y": 110, "w": 180, "h": 70, "sys": "economy", "detail": "Five stories: SSP1 Sustainability, SSP2 Middle of the road, SSP3 Regional rivalry, SSP4 Inequality, SSP5 Fossil-fuelled development."}, {"id": "drivers", "label": "Drivers", "sub": "population, GDP, diets, tech", "x": 120, "y": 290, "w": 180, "h": 70, "sys": "economy", "detail": "Each story is turned into numbers: population, income, urbanisation, and assumptions about technology and diets."}, {"id": "rcp", "label": "Forcing target", "sub": "1.9 to 8.5 W/m² in 2100", "x": 420, "y": 110, "w": 190, "h": 70, "sys": "climate", "detail": "Inherited from the Representative Concentration Pathways (RCPs). The number names the extra heat trapped in 2100."}, {"id": "iam", "label": "IAM", "sub": "finds an energy and land system", "x": 420, "y": 290, "w": 190, "h": 70, "sys": "energy", "detail": "The model's job: work out the energy and land system that connects a given SSP to a given forcing level, often with a carbon price."}, {"id": "label", "label": "Scenario label", "sub": "e.g. SSP2-4.5", "x": 720, "y": 110, "w": 180, "h": 70, "sys": "data", "detail": "SSP2-4.5 = middle-of-the-road story pushed to 4.5 W/m², roughly 2.7 °C of warming (AR6 WGI estimate; check before teaching)."}, {"id": "ar6", "label": "AR6 categories", "sub": "C1 to C8 by warming", "x": 720, "y": 290, "w": 180, "h": 70, "sys": "climate", "detail": "The IPCC's 2022 report collected about 3,000 pathways and sorted 1,202 into categories: C1 = 1.5 °C with little or no overshoot … C8 = above 4 °C."}, {"id": "cmip7", "label": "CMIP7 (2026)", "sub": "7 scenarios, one per IAM", "x": 720, "y": 450, "w": 180, "h": 64, "sys": "policy", "detail": "The next generation for climate models: seven scenarios, each produced by a different IAM team. The high one (H) was made with GCAM."}], "edges": [{"from": "ssp", "to": "drivers", "label": "quantified as", "sys": "economy"}, {"from": "drivers", "to": "iam", "label": "inputs", "sys": "economy"}, {"from": "rcp", "to": "iam", "label": "target", "sys": "climate"}, {"from": "iam", "to": "label", "label": "named", "sys": "data"}, {"from": "iam", "to": "ar6", "label": "sorted by warming", "sys": "climate"}, {"from": "ar6", "to": "cmip7", "label": "next generation", "sys": "policy"}], "tour": [{"focus": ["ssp"], "edges": [], "text": "First choose a story about society: one of five Shared Socioeconomic Pathways."}, {"focus": ["drivers"], "edges": [["ssp", "drivers"]], "text": "The story is turned into numbers: population, income, diets and technology assumptions."}, {"focus": ["rcp"], "edges": [], "text": "Separately, choose a climate outcome: the extra heat trapped in 2100, from 1.9 to 8.5 W/m²."}, {"focus": ["iam"], "edges": [["drivers", "iam"], ["rcp", "iam"]], "text": "The IAM works out an energy and land system that joins the story to the forcing level, if one exists."}, {"focus": ["label", "ar6"], "edges": [["iam", "label"], ["iam", "ar6"]], "text": "The result gets a label like SSP2-4.5, and the IPCC sorts pathways into categories C1 to C8 by warming."}, {"focus": ["cmip7"], "edges": [["ar6", "cmip7"]], "text": "Scenarios get updated: CMIP7 (2026) has seven scenarios, each from a different IAM. GCAM made the high one."}]}, "m1.6": {"title": "A tour of GCAM", "caption": "Notice that energy, land and water are linked by bioenergy, cooling water and land carbon, and that all of them feed emissions to Hector.", "nodes": [{"id": "socio", "label": "Population and GDP", "sub": "32 regions, SSP inputs", "x": 120, "y": 90, "w": 190, "h": 70, "sys": "economy", "detail": "GCAM v8.2 documentation: 32 energy-economy regions. Population and GDP come from the chosen SSP and drive demand."}, {"id": "time", "label": "Time steps", "sub": "2021 base, then every 5 years", "x": 420, "y": 60, "w": 200, "h": 64, "sys": "data", "detail": "Calibrated to a 2021 base year, then solved every five years to 2100. Recursive-dynamic: no foresight; each period is solved in turn."}, {"id": "markets", "label": "Marketplace", "sub": "prices adjust until all clear", "x": 750, "y": 90, "w": 210, "h": 70, "sys": "economy", "detail": "An auctioneer: prices of fuels, crops, land and water move until supply equals demand in every market at once, every period."}, {"id": "energy", "label": "Energy", "sub": "supply, power, buildings, transport", "x": 170, "y": 280, "w": 230, "h": 80, "sys": "energy", "detail": "Energy resources are turned into electricity, fuels and hydrogen, and used in buildings, industry and transport. Technologies compete by cost."}, {"id": "land", "label": "Land", "sub": "300+ units: crops, forests, bio", "x": 450, "y": 280, "w": 210, "h": 80, "sys": "land", "detail": "More than 300 land units (the documentation also gives 396). Land is shared among crops, pasture, forest and bioenergy by profit."}, {"id": "water", "label": "Water", "sub": "235 river basins", "x": 730, "y": 280, "w": 200, "h": 80, "sys": "water", "detail": "235 river basins. Farms, power plants, industry and cities withdraw water; supply grows costlier as basins are stressed."}, {"id": "emis", "label": "Emissions", "sub": "CO2 and other gases", "x": 300, "y": 450, "w": 190, "h": 64, "sys": "climate", "detail": "Counted from fuels burned and land changed, for CO<sub>2</sub> and many other gases."}, {"id": "hector", "label": "Hector climate model", "sub": "concentrations to °C", "x": 620, "y": 450, "w": 210, "h": 64, "sys": "climate", "detail": "GCAM passes emissions to Hector at each step; Hector returns concentrations, forcing and temperature."}], "edges": [{"from": "socio", "to": "energy", "label": "demand", "sys": "economy"}, {"from": "socio", "to": "land", "label": "food demand", "sys": "economy"}, {"from": "markets", "to": "energy", "label": "prices", "sys": "economy"}, {"from": "markets", "to": "water", "label": "water prices", "sys": "economy"}, {"from": "land", "to": "energy", "label": "bioenergy", "sys": "land"}, {"from": "water", "to": "energy", "label": "cooling water", "sys": "water"}, {"from": "energy", "to": "emis", "label": "fuel CO2", "sys": "energy"}, {"from": "land", "to": "emis", "label": "land-use CO2", "sys": "land"}, {"from": "emis", "to": "hector", "label": "every step", "sys": "climate"}], "tour": [{"focus": ["socio"], "edges": [], "text": "GCAM splits the world into 32 regions. Population and GDP from an SSP set what each region wants."}, {"focus": ["time"], "edges": [], "text": "It starts from a calibrated 2021 base year and steps forward five years at a time to 2100, without looking ahead."}, {"focus": ["markets"], "edges": [["markets", "energy"], ["markets", "water"]], "text": "In each step an auctioneer adjusts prices until supply equals demand in every market at once."}, {"focus": ["energy", "land", "water"], "edges": [["socio", "energy"], ["socio", "land"]], "text": "Energy, land and water are modelled region by region, basin by basin."}, {"focus": ["land", "water", "energy"], "edges": [["land", "energy"], ["water", "energy"]], "text": "They are linked: bioenergy needs land, power plants need cooling water, and a carbon price reaches forests."}, {"focus": ["emis", "hector"], "edges": [["energy", "emis"], ["land", "emis"], ["emis", "hector"]], "text": "Emissions from energy and land go to Hector, the simple climate model inside GCAM, every step."}]}, "m2.1": {"title": "Drivers in, demands out", "caption": "Population and labour productivity are inputs; GDP per person then drives every demand. Click a box, or press Play.", "nodes": [{"id": "pop", "label": "Population", "sub": "SSP database, by region", "x": 130, "y": 90, "w": 180, "h": 64, "sys": "economy", "detail": "Population by region comes from the SSP database for 2015 to 2100 (UN data before that). In 2100: SSP1 6.9, SSP2 9, SSP3 12.7, SSP5 7.4 billion (ssp.html)."}, {"id": "lab", "label": "Labour productivity", "sub": "growth rate, exogenous", "x": 130, "y": 260, "w": 180, "h": 64, "sys": "economy", "detail": "An exogenous growth rate per region. With labour force participation it sets how fast output per worker grows (economy.html, Table 1)."}, {"id": "gdp", "label": "GDP and GDP per person", "sub": "32 regions, 5-year steps", "x": 450, "y": 260, "w": 210, "h": 64, "sys": "economy", "detail": "Regional GDP is the scale of economic activity. Calibrated to history up to the 2021 base year, then projected to 2100 in 5-year steps."}, {"id": "bld", "label": "Buildings", "sub": "floorspace, services", "x": 770, "y": 90, "w": 180, "h": 64, "sys": "energy", "detail": "Floorspace per person follows a Gompertz curve in income; services per m² saturate as income rises (demand_energy.html)."}, {"id": "trn", "label": "Transport and industry", "sub": "service demand", "x": 770, "y": 260, "w": 180, "h": 64, "sys": "energy", "detail": "Service output grows with income (elasticity α) and falls with price (β): D_t = D_t-1 (Y ratio)^α (P ratio)^β (N ratio)."}, {"id": "food", "label": "Food and land", "sub": "staples, non-staples", "x": 770, "y": 430, "w": 180, "h": 64, "sys": "land", "detail": "Food demand uses an income-dependent demand system (Edmonds et al. 2017): richer diets shift from staples to meat and dairy (demand_land.html)."}, {"id": "wat", "label": "Municipal water", "sub": "per-person demand", "x": 450, "y": 450, "w": 180, "h": 64, "sys": "water", "detail": "Per-capita municipal water grows with GDP per person (elasticity 0.37) and falls with price (−0.33) and technology (demand_water.html)."}, {"id": "macro", "label": "Macro module", "sub": "KLEM → KLEAM (v9.0)", "x": 130, "y": 430, "w": 180, "h": 64, "sys": "economy", "detail": "Since GCAM v7 a CES production function can make GDP respond to energy: energy service efficiency, energy investment and net exports enter (economy.html). v9.0 adds agriculture (KLEAM)."}], "edges": [{"from": "pop", "to": "gdp", "label": "people", "sys": "economy"}, {"from": "lab", "to": "gdp", "label": "output per worker", "sys": "economy"}, {"from": "gdp", "to": "bld", "label": "income", "sys": "economy"}, {"from": "gdp", "to": "trn", "label": "income", "sys": "economy"}, {"from": "gdp", "to": "food", "label": "income", "sys": "economy"}, {"from": "gdp", "to": "wat", "label": "income", "sys": "economy"}, {"from": "macro", "to": "gdp", "label": "energy feedback", "sys": "economy"}], "tour": [{"focus": ["pop"], "edges": [["pop", "gdp"]], "text": "Start with people. Population is an input from the SSP database, different in each storyline."}, {"focus": ["lab"], "edges": [["lab", "gdp"]], "text": "Labour productivity growth decides how much each worker produces. Together with population it sets GDP."}, {"focus": ["gdp"], "edges": [], "text": "GDP per person is the single most important driver in GCAM. Watch where it flows next."}, {"focus": ["bld", "trn"], "edges": [["gdp", "bld"], ["gdp", "trn"]], "text": "Energy services grow with income: more floorspace, more travel, more industrial output."}, {"focus": ["food", "wat"], "edges": [["gdp", "food"], ["gdp", "wat"]], "text": "Diets and municipal water use also follow income, so land and water demand grow too."}, {"focus": ["macro"], "edges": [["macro", "gdp"]], "text": "Optional feedback: the macro module lets energy costs change GDP, closing the loop."}]}, "m2.2": {"title": "One period of the GCAM auction", "caption": "Each period the solver adjusts prices until excess demand is near zero in every market, then the model steps 5 years ahead.", "nodes": [{"id": "guess", "label": "Trial prices", "sub": "log prices, all markets", "x": 130, "y": 90, "w": 180, "h": 64, "sys": "economy", "detail": "The solver starts from the previous period's prices (plus a preconditioner that nudges bad starting guesses, for example resource turn-on prices) (solver.html)."}, {"id": "sup", "label": "Supply bids", "sub": "energy, crops, water", "x": 770, "y": 90, "w": 180, "h": 64, "sys": "energy", "detail": "Every supply sector reports how much it would produce at the trial prices: resource curves, power plants, farms, water sources."}, {"id": "dem", "label": "Demand bids", "sub": "buildings, transport, food", "x": 770, "y": 260, "w": 180, "h": 64, "sys": "land", "detail": "Every demand sector reports how much it would buy at those prices."}, {"id": "ed", "label": "Excess demand F(p)", "sub": "demand − supply, scaled", "x": 450, "y": 260, "w": 200, "h": 64, "sys": "economy", "detail": "F(p) = D(p) − S(p) for each market. GCAM scales excess demand so markets of different sizes are comparable, and works in log prices."}, {"id": "broy", "label": "Broyden update", "sub": "B·δx = −F(x)", "x": 130, "y": 430, "w": 180, "h": 64, "sys": "economy", "detail": "Broyden's method solves B·δx = −F(x) with B a secant approximation of the Jacobian, cutting the step back if it makes things worse. Bisection helps near singular regions (solver.html)."}, {"id": "ok", "label": "All markets clear?", "sub": "tolerance 0.001 (example)", "x": 450, "y": 450, "w": 180, "h": 64, "sys": "policy", "detail": "Solved when relative excess demand is below solution-tolerance (example 0.001) with a floor (0.0001). Otherwise iterate, up to max-model-calcs (example 2500)."}, {"id": "next", "label": "Next period", "sub": "+5 years, no foresight", "x": 770, "y": 430, "w": 180, "h": 64, "sys": "climate", "detail": "Recursive dynamics: the solved period is fixed, emissions go to Hector, and the model moves to the next 5-year step using what it knows now (overview.html)."}], "edges": [{"from": "guess", "to": "sup", "label": "prices", "sys": "economy"}, {"from": "guess", "to": "dem", "label": "", "sys": "economy"}, {"from": "sup", "to": "ed", "label": "quantities"}, {"from": "dem", "to": "ed", "label": "quantities"}, {"from": "ed", "to": "broy", "label": "residuals", "sys": "economy"}, {"from": "broy", "to": "guess", "label": "new prices", "sys": "economy"}, {"from": "ed", "to": "ok", "label": "check"}, {"from": "ok", "to": "next", "label": "yes"}], "tour": [{"focus": ["guess"], "edges": [], "text": "The auctioneer calls out a trial price for every market: energy, crops, land, water, and any policy markets."}, {"focus": ["sup", "dem"], "edges": [["guess", "sup"], ["guess", "dem"]], "text": "Every supplier and every buyer answers: this is how much I would sell, or buy, at those prices."}, {"focus": ["ed"], "edges": [["sup", "ed"], ["dem", "ed"]], "text": "The gap demand minus supply, market by market, is the excess-demand vector F(p). The target is F(p) ≈ 0 everywhere."}, {"focus": ["broy"], "edges": [["ed", "broy"], ["broy", "guess"]], "text": "Broyden's method uses the gaps to move all prices together, learning how markets react to each other as it goes."}, {"focus": ["ok"], "edges": [["ed", "ok"]], "text": "When every gap is within tolerance, the period is solved. If not, iterate again."}, {"focus": ["next"], "edges": [["ok", "next"]], "text": "Then step 5 years ahead. Decisions already made stay made: GCAM does not see the future."}]}, "m2.3": {"title": "Nested choice for electricity", "caption": "Each level of the tree has its own logit. Costs flow up the tree; shares flow down it.", "nodes": [{"id": "elec", "label": "Electricity sector", "sub": "demand to be met", "x": 450, "y": 70, "w": 200, "h": 64, "sys": "energy", "detail": "The sector's output must meet demand. It splits its market among subsectors (fuels) with a logit; electricity subsector exponent in the reference example is −3 (choice.html)."}, {"id": "coal", "label": "Coal subsector", "sub": "logit among plants", "x": 130, "y": 90, "w": 180, "h": 64, "sys": "energy", "detail": "Within coal, technologies compete with an aggressive exponent (−10 in the reference example): small cost differences swing shares a lot."}, {"id": "gas", "label": "Gas subsector", "sub": "", "x": 450, "y": 260, "w": 180, "h": 64, "sys": "energy", "detail": "Gas plants (combined cycle, turbines, with or without CCS) share the gas subsector by their own logit."}, {"id": "sol", "label": "Solar subsector", "sub": "PV, CSP, rooftop", "x": 770, "y": 90, "w": 180, "h": 64, "sys": "energy", "detail": "Solar technologies; their effective cost includes a value-factor adjustment that rises with market share (Go 2.4)."}, {"id": "pc", "label": "Pulverised coal", "sub": "cost incl. fuel + carbon", "x": 130, "y": 260, "w": 180, "h": 64, "sys": "energy", "detail": "A technology: cost = non-energy cost + fuel cost + emissions cost (en_technologies.html)."}, {"id": "ccs", "label": "Coal with CCS", "sub": "", "x": 130, "y": 400, "w": 180, "h": 64, "sys": "energy", "detail": "Higher non-energy cost, but much lower emissions cost under a carbon price."}, {"id": "cool", "label": "Cooling system", "sub": "once-through, recirculating…", "x": 450, "y": 440, "w": 210, "h": 64, "sys": "water", "detail": "For thermal plants the last level chooses one of up to five cooling systems, by a cost logit that includes water prices (demand_water.html)."}, {"id": "sw", "label": "Share weights", "sub": "calibrated to 2021", "x": 770, "y": 260, "w": 180, "h": 64, "sys": "data", "detail": "Share weights scale each option so base-year shares match history; they also phase in new technologies (choice.html)."}], "edges": [{"from": "elec", "to": "coal", "label": "share", "sys": "energy"}, {"from": "elec", "to": "gas", "label": "share", "sys": "energy"}, {"from": "elec", "to": "sol", "label": "share", "sys": "energy"}, {"from": "coal", "to": "pc", "label": "", "sys": "energy"}, {"from": "coal", "to": "ccs", "label": "", "sys": "energy"}, {"from": "gas", "to": "cool", "label": "", "sys": "water"}, {"from": "sw", "to": "sol", "label": "calibrates", "sys": "neutral"}], "tour": [{"focus": ["elec"], "edges": [], "text": "Electricity demand must be met. The sector does not pick one fuel: it shares the market."}, {"focus": ["coal", "gas", "sol"], "edges": [["elec", "coal"], ["elec", "gas"], ["elec", "sol"]], "text": "First level: fuels compete by cost with a moderate exponent (−3 in the reference example)."}, {"focus": ["pc", "ccs"], "edges": [["coal", "pc"], ["coal", "ccs"]], "text": "Inside coal, technologies compete with a steep exponent (−10): close substitutes switch quickly."}, {"focus": ["cool"], "edges": [["gas", "cool"]], "text": "Thermal plants then choose a cooling system, linking electricity to water prices."}, {"focus": ["sw"], "edges": [["sw", "sol"]], "text": "Share weights calibrate each branch to 2021 data and phase new options in."}]}, "m2.4": {"title": "From resources to delivered electricity", "caption": "Resources feed conversion technologies; each technology's cost includes fuel and carbon, and wind/solar get a value-factor adjustment.", "nodes": [{"id": "fos", "label": "Fossil resources", "sub": "graded supply curves", "x": 130, "y": 90, "w": 180, "h": 64, "sys": "energy", "detail": "Coal, oil, gas, uranium: graded curves inside a resource/reserve model; cheap grades first, price rises with use (supply_energy.html). Files A11.fos_curves.csv, A12.U_curves.csv."}, {"id": "ren", "label": "Renewable resources", "sub": "wind, solar, geothermal, hydro", "x": 130, "y": 260, "w": 180, "h": 64, "sys": "energy", "detail": "Annual flows with supply curves Q = max·P^b/(Mid^b + P^b). Hydropower is exogenous fixed output; utility solar is nearly unlimited at low price (supply_energy.html)."}, {"id": "bio", "label": "Bioenergy", "sub": "from land (Go 2.6)", "x": 130, "y": 430, "w": 180, "h": 64, "sys": "land", "detail": "Purpose-grown energy crops, residues and waste come from the land module and compete with food for land."}, {"id": "plant", "label": "Power plants", "sub": "cost = non-energy + fuel + carbon", "x": 450, "y": 260, "w": 220, "h": 64, "sys": "energy", "detail": "Non-energy cost is levelised: overnight capital × capital recovery factor ÷ capacity factor + O&M. Costs from NREL ATB, updated in v8.8 (en_technologies.html)."}, {"id": "vf", "label": "Value factor", "sub": "PLCOE = LCOE / VF", "x": 770, "y": 90, "w": 180, "h": 64, "sys": "energy", "detail": "Since v7.3 wind and solar cost is divided by a value factor that falls linearly with market share, e.g. PV intercept 0.972, slope −1.443 (CMP 394)."}, {"id": "ccs", "label": "Carbon capture", "sub": "remove-fraction → storage", "x": 770, "y": 260, "w": 180, "h": 64, "sys": "climate", "detail": "CCS is a remove-fraction on a technology's emissions, sent to a storage market (en_technologies.html)."}, {"id": "grid", "label": "Electricity market", "sub": "sector logit, price", "x": 770, "y": 430, "w": 180, "h": 64, "sys": "economy", "detail": "Technologies share the electricity market by nested logit; the solved price feeds buildings, industry and transport."}, {"id": "cp", "label": "Carbon price", "sub": "$/t added to cost", "x": 450, "y": 450, "w": 180, "h": 64, "sys": "policy", "detail": "Adds emission factor × carbon price to each technology's cost."}], "edges": [{"from": "fos", "to": "plant", "label": "fuel", "sys": "energy"}, {"from": "ren", "to": "plant", "label": "resource", "sys": "energy"}, {"from": "bio", "to": "plant", "label": "biomass", "sys": "land"}, {"from": "plant", "to": "grid", "label": "output", "sys": "energy"}, {"from": "vf", "to": "plant", "label": "adjusts VRE cost", "sys": "energy"}, {"from": "plant", "to": "ccs", "label": "captured CO₂", "sys": "climate"}, {"from": "cp", "to": "plant", "label": "+ ef × price", "sys": "policy"}], "tour": [{"focus": ["fos"], "edges": [["fos", "plant"]], "text": "Fossil fuels come from graded curves: the more you extract, the higher the cost of the next grade."}, {"focus": ["ren", "bio"], "edges": [["ren", "plant"], ["bio", "plant"]], "text": "Renewables are flows with their own curves; bioenergy arrives from the land module."}, {"focus": ["plant"], "edges": [], "text": "Each plant's cost = non-energy (capital, O&M) + fuel ÷ efficiency + emissions cost."}, {"focus": ["cp"], "edges": [["cp", "plant"]], "text": "A carbon price adds emission factor × price: gas rises ~$18/MWh per $50/t in the kit example."}, {"focus": ["vf"], "edges": [["vf", "plant"]], "text": "Wind and solar cost is divided by a value factor that shrinks as their share grows, slowing their growth."}, {"focus": ["ccs", "grid"], "edges": [["plant", "ccs"], ["plant", "grid"]], "text": "CCS sends captured CO₂ to storage; technologies share the electricity market by logit."}]}, "m2.5": {"title": "Energy demand: services first, fuels second", "caption": "Income and prices set service demand; technologies then choose fuels. Electricity prices reach every end use.", "nodes": [{"id": "inc", "label": "Income and population", "sub": "from Go 2.1", "x": 130, "y": 260, "w": 180, "h": 64, "sys": "economy", "detail": "GDP per person drives floorspace, industrial output and passenger travel through income elasticities (demand_energy.html)."}, {"id": "bld", "label": "Buildings", "sub": "floorspace × services", "x": 130, "y": 90, "w": 180, "h": 64, "sys": "energy", "detail": "Residential split into 10 income deciles since v7.1. Floorspace follows a Gompertz curve; heating and cooling depend on degree-days (demand_energy.html)."}, {"id": "ind", "label": "Industry", "sub": "steel, cement, chemicals…", "x": 450, "y": 70, "w": 180, "h": 64, "sys": "energy", "detail": "Iron and steel, chemicals, aluminium, cement, fertiliser, food processing and other industry, plus construction, mining and agricultural energy use."}, {"id": "trn", "label": "Transport", "sub": "passenger + freight", "x": 450, "y": 260, "w": 180, "h": 64, "sys": "energy", "detail": "Four final demands: passenger aviation, other passenger, international shipping, other freight. Nested modes, size classes and drivetrains (Go 3 goes deep)."}, {"id": "vot", "label": "Value of time", "sub": "wage ÷ speed", "x": 130, "y": 430, "w": 180, "h": 64, "sys": "economy", "detail": "Passenger mode cost adds W·V/S: wage per hour × time-value multiplier ÷ speed. Faster modes win as wages rise."}, {"id": "elecp", "label": "Electricity price", "sub": "from Go 2.4", "x": 770, "y": 90, "w": 180, "h": 64, "sys": "energy", "detail": "Electric technologies (heat pumps, EVs, electric arc furnaces) pay the solved electricity price, so cheaper power pulls demand toward electricity."}, {"id": "fuel", "label": "Final energy by fuel", "sub": "EJ by sector", "x": 770, "y": 260, "w": 180, "h": 64, "sys": "energy", "detail": "Technology choice inside each service turns service demand into final energy by fuel."}, {"id": "co2", "label": "Emissions", "sub": "fuel × carbon coefficient", "x": 770, "y": 430, "w": 180, "h": 64, "sys": "climate", "detail": "Combustion CO₂ = fuel use × carbon coefficient; cooling electricity also drives HFC134a (emissions.html)."}], "edges": [{"from": "inc", "to": "bld", "label": "income", "sys": "economy"}, {"from": "inc", "to": "ind", "label": "", "sys": "economy"}, {"from": "inc", "to": "trn", "label": "income", "sys": "economy"}, {"from": "vot", "to": "trn", "label": "time cost", "sys": "economy"}, {"from": "elecp", "to": "fuel", "label": "price signal", "sys": "energy"}, {"from": "trn", "to": "fuel", "label": "service → fuel", "sys": "energy"}, {"from": "bld", "to": "fuel", "label": "", "sys": "energy"}, {"from": "fuel", "to": "co2", "label": "", "sys": "climate"}], "tour": [{"focus": ["inc"], "edges": [], "text": "Income per person, from Go 2.1, is the main driver of how much service people demand."}, {"focus": ["bld", "ind"], "edges": [["inc", "bld"], ["inc", "ind"]], "text": "Buildings and industry grow with income and fall with service price; floorspace saturates."}, {"focus": ["trn", "vot"], "edges": [["inc", "trn"], ["vot", "trn"]], "text": "Transport adds the value of time: richer travellers choose faster modes even if dearer."}, {"focus": ["elecp", "fuel"], "edges": [["elecp", "fuel"], ["trn", "fuel"], ["bld", "fuel"]], "text": "Inside each service, technologies compete by cost, so electricity prices steer heat pumps and EVs."}, {"focus": ["co2"], "edges": [["fuel", "co2"]], "text": "Final energy by fuel times carbon coefficients gives demand-side emissions."}]}, "m2.6": {"title": "Land competition and its links", "caption": "Profit per hectare sets land shares; bioenergy demand and carbon prices change profits, and land change releases or stores carbon.", "nodes": [{"id": "price", "label": "Crop and biomass prices", "sub": "from food and energy markets", "x": 130, "y": 90, "w": 180, "h": 64, "sys": "economy", "detail": "Crop prices clear food markets; the biomass price clears the bioenergy market that the energy system demands from (supply_land.html)."}, {"id": "profit", "label": "Profit per hectare", "sub": "(price − cost) × yield", "x": 450, "y": 70, "w": 180, "h": 64, "sys": "land", "detail": "Profit rate = (price + subsidy − variable cost − input costs) × yield, in 1975$ per area; input costs include fertiliser and water (supply_land.html)."}, {"id": "cpr", "label": "Carbon price on land", "sub": "subsidy for carbon stock", "x": 770, "y": 90, "w": 180, "h": 64, "sys": "policy", "detail": "Landowners receive carbon price × carbon density (discounted, annualised): forests gain relative to cropland (land.html)."}, {"id": "nest", "label": "Land nest (logit)", "sub": "s = (λπ)^ρ / Σ(λπ)^ρ", "x": 450, "y": 260, "w": 210, "h": 64, "sys": "land", "detail": "Shares by profit with exponent ρ > 0; tighter substitution inside nests than across them. Calibrated profit scalers λ reproduce base-year land (land.html)."}, {"id": "crop", "label": "Cropland and food", "sub": "irrigated/rainfed × hi/lo", "x": 130, "y": 260, "w": 180, "h": 64, "sys": "land", "detail": "Every crop splits into irrigated/rainfed × high/low management, allowing price-induced intensification."}, {"id": "bioc", "label": "Energy crops", "sub": "herbaceous grass from 2025", "x": 130, "y": 430, "w": 180, "h": 64, "sys": "energy", "detail": "Dedicated energy grass enters the cropland nest; woody biomass sits in the forest nest (details_land.html)."}, {"id": "forest", "label": "Forest and natural land", "sub": "managed / unmanaged", "x": 770, "y": 260, "w": 180, "h": 64, "sys": "land", "detail": "Forests grow back slowly: uptake follows a sigmoid with mature age of about 30–100 years (land.html)."}, {"id": "luc", "label": "Land-use change CO₂", "sub": "ΔA × carbon density", "x": 770, "y": 430, "w": 180, "h": 64, "sys": "climate", "detail": "E_t = A_t·D_t − A_t−1·D_t−1 for vegetation and soil. Releases are immediate; regrowth uptake is slow (land.html)."}], "edges": [{"from": "price", "to": "profit", "label": "price", "sys": "economy"}, {"from": "profit", "to": "nest", "label": "profit", "sys": "land"}, {"from": "cpr", "to": "nest", "label": "subsidy", "sys": "policy"}, {"from": "nest", "to": "crop", "label": "share", "sys": "land"}, {"from": "nest", "to": "bioc", "label": "share", "sys": "land"}, {"from": "nest", "to": "forest", "label": "share", "sys": "land"}, {"from": "forest", "to": "luc", "label": "", "sys": "climate"}, {"from": "bioc", "to": "price", "label": "supply", "sys": "energy"}], "tour": [{"focus": ["price", "profit"], "edges": [["price", "profit"]], "text": "Prices from food and bioenergy markets set each land use's profit per hectare."}, {"focus": ["nest"], "edges": [["profit", "nest"]], "text": "A logit on profit shares the land: more profitable uses expand, but not all at once."}, {"focus": ["crop", "bioc"], "edges": [["nest", "crop"], ["nest", "bioc"]], "text": "Energy grass and food crops compete in the same cropland nest: bioenergy demand raises food prices."}, {"focus": ["cpr", "forest"], "edges": [["cpr", "nest"], ["nest", "forest"]], "text": "A carbon price on land pays for stored carbon, so forests become more profitable and can expand."}, {"focus": ["luc"], "edges": [["forest", "luc"]], "text": "Every change in land cover changes carbon stocks: clearing releases CO₂ fast, regrowth takes it back slowly."}, {"focus": ["bioc", "price"], "edges": [["bioc", "price"]], "text": "Biomass supply feeds back to the bioenergy market, closing the energy–land loop."}]}, "m2.7": {"title": "A basin water market", "caption": "Six demand sectors withdraw water; three supply tiers meet it; the basin price feeds back to cooling choice and irrigation.", "nodes": [{"id": "irr", "label": "Irrigation", "sub": "km³ per Mt of crop", "x": 130, "y": 90, "w": 180, "h": 64, "sys": "land", "detail": "Irrigation withdrawals = exogenous coefficient × endogenous crop production, by basin (demand_water.html)."}, {"id": "pow", "label": "Power cooling", "sub": "5 cooling options", "x": 130, "y": 260, "w": 180, "h": 64, "sys": "energy", "detail": "Once-through, recirculating, pond, dry and seawater once-through, chosen by a cost logit; dry cooling lowers plant efficiency (demand_water.html)."}, {"id": "mun", "label": "Municipal and industry", "sub": "grow with income", "x": 130, "y": 430, "w": 180, "h": 64, "sys": "economy", "detail": "Per-capita municipal water grows with GDP per person (elasticity 0.37) and falls with price (−0.33) and technology."}, {"id": "bas", "label": "Basin water market", "sub": "price in 1975$/m³", "x": 450, "y": 260, "w": 200, "h": 64, "sys": "water", "detail": "235 basins. A basin shadow price adjusts until demand equals supply (supply_water.html)."}, {"id": "ren", "label": "Renewable water", "sub": "accessible runoff (Xanthos)", "x": 770, "y": 90, "w": 180, "h": 64, "sys": "water", "detail": "Accessible water QA = max(0, min(QT − EFR, QB − EFR + RS)) from Xanthos runoff, environmental flows and reservoir storage. Cheap within the accessible amount."}, {"id": "gw", "label": "Groundwater", "sub": "graded, Superwell", "x": 770, "y": 260, "w": 180, "h": 64, "sys": "water", "detail": "Non-renewable groundwater as a graded depletable resource; Superwell gives 20 cost grades per region-basin."}, {"id": "des", "label": "Desalination", "sub": "cities and industry only", "x": 770, "y": 430, "w": 180, "h": 64, "sys": "energy", "detail": "Costs are energy, capital and O&M; reverse osmosis uses 2.75 kWh/m³. In core runs only municipal and industrial demand can use it."}, {"id": "efw", "label": "Energy for water", "sub": "kWh per m³", "x": 450, "y": 450, "w": 180, "h": 64, "sys": "energy", "detail": "Pumping, treatment and desalination use electricity: a water → energy link (demand_energy.html)."}], "edges": [{"from": "irr", "to": "bas", "label": "withdrawals", "sys": "land"}, {"from": "pow", "to": "bas", "label": "withdrawals", "sys": "energy"}, {"from": "mun", "to": "bas", "label": "withdrawals", "sys": "economy"}, {"from": "ren", "to": "bas", "label": "tier 1", "sys": "water"}, {"from": "gw", "to": "bas", "label": "tier 2", "sys": "water"}, {"from": "des", "to": "bas", "label": "tier 3", "sys": "water"}, {"from": "bas", "to": "pow", "label": "price", "sys": "water"}, {"from": "des", "to": "efw", "label": "electricity", "sys": "energy"}], "tour": [{"focus": ["irr", "pow", "mun"], "edges": [["irr", "bas"], ["pow", "bas"], ["mun", "bas"]], "text": "Farms, power plants, cities and industry all withdraw from the same basin."}, {"focus": ["ren"], "edges": [["ren", "bas"]], "text": "Accessible renewable water is used first, and it is cheap."}, {"focus": ["gw"], "edges": [["gw", "bas"]], "text": "When it runs short, groundwater on graded cost curves fills the gap at a higher price."}, {"focus": ["des", "efw"], "edges": [["des", "bas"], ["des", "efw"]], "text": "Desalination is the last resort for cities and industry, and it uses electricity."}, {"focus": ["bas", "pow"], "edges": [["bas", "pow"]], "text": "The basin price feeds back: power plants shift to cooling that uses less water."}]}, "m2.8": {"title": "The whole system and its feedbacks", "caption": "Five loops to trace: bioenergy–food, carbon–forest, electricity–transport, water–cooling, and emissions–climate–policy.", "nodes": [{"id": "econ", "label": "Economy", "sub": "population, GDP", "x": 130, "y": 90, "w": 160, "h": 64, "sys": "economy", "detail": "Population and GDP drive every demand (Go 2.1). In open-GDP mode energy feeds back to GDP."}, {"id": "mkt", "label": "Markets and solver", "sub": "prices clear all markets", "x": 450, "y": 70, "w": 190, "h": 64, "sys": "economy", "detail": "Broyden's method clears a few hundred markets each period (Go 2.2)."}, {"id": "en", "label": "Energy", "sub": "supply and demand", "x": 770, "y": 90, "w": 160, "h": 64, "sys": "energy", "detail": "Resources, conversion and end uses (Go 2.4, 2.5). Shares by nested logit (Go 2.3)."}, {"id": "land", "label": "Land and food", "sub": "profit-based logit", "x": 130, "y": 260, "w": 160, "h": 64, "sys": "land", "detail": "Crops, pasture, forest and energy crops share land by profit (Go 2.6)."}, {"id": "water", "label": "Water", "sub": "235 basins", "x": 130, "y": 430, "w": 160, "h": 64, "sys": "water", "detail": "Basin prices from renewable, groundwater and desalination tiers (Go 2.7)."}, {"id": "emis", "label": "Emissions", "sub": "CO₂, LUC, non-CO₂", "x": 450, "y": 260, "w": 180, "h": 64, "sys": "climate", "detail": "CO₂ from fuels × carbon coefficients, land-use change CO₂, and non-CO₂ gases with MAC curves (emissions.html)."}, {"id": "hec", "label": "Hector", "sub": "concentrations → °C", "x": 770, "y": 430, "w": 170, "h": 64, "sys": "climate", "detail": "Each period GCAM passes emissions to Hector v3.2, which computes concentrations, forcing and global temperature (hector.html)."}, {"id": "pol", "label": "Policy", "sub": "price, cap, target", "x": 770, "y": 260, "w": 160, "h": 64, "sys": "policy", "detail": "fixedTax price paths, emissions constraints solved for a price, or climate targets via target-finder mode (policies.html)."}, {"id": "ref", "label": "Reference vs policy", "sub": "the difference is the result", "x": 450, "y": 450, "w": 200, "h": 64, "sys": "data", "detail": "Results are read as policy run minus reference run; never as forecasts."}], "edges": [{"from": "econ", "to": "mkt", "label": "demand drivers", "sys": "economy"}, {"from": "mkt", "to": "en", "label": "prices", "sys": "economy"}, {"from": "mkt", "to": "land", "label": "prices", "sys": "economy"}, {"from": "en", "to": "land", "label": "bioenergy demand", "sys": "energy"}, {"from": "water", "to": "en", "label": "cooling cost", "sys": "water"}, {"from": "en", "to": "emis", "label": "fuel CO₂", "sys": "climate"}, {"from": "land", "to": "emis", "label": "LUC CO₂", "sys": "climate"}, {"from": "emis", "to": "hec", "label": "emissions", "sys": "climate"}, {"from": "pol", "to": "en", "label": "carbon price", "sys": "policy"}, {"from": "pol", "to": "land", "label": "land carbon", "sys": "policy"}, {"from": "hec", "to": "pol", "label": "target check", "sys": "climate"}], "tour": [{"focus": ["econ", "mkt"], "edges": [["econ", "mkt"]], "text": "Drivers set demands; the solver finds prices that clear every market in the period."}, {"focus": ["en", "land"], "edges": [["mkt", "en"], ["mkt", "land"], ["en", "land"]], "text": "Loop 1, bioenergy–food: energy demand for biomass raises land and food prices."}, {"focus": ["pol", "land"], "edges": [["pol", "land"]], "text": "Loop 2, carbon–forest: a carbon price on land pays for stored carbon and expands forests."}, {"focus": ["water", "en"], "edges": [["water", "en"]], "text": "Loop 3, water–cooling: scarce basins raise water prices and shift power-plant cooling."}, {"focus": ["pol", "en"], "edges": [["pol", "en"]], "text": "Loop 4, electricity–transport: carbon prices change electricity costs, shifting EVs and heat pumps."}, {"focus": ["emis", "hec"], "edges": [["en", "emis"], ["land", "emis"], ["emis", "hec"]], "text": "All emissions go to Hector, which returns concentrations, forcing and temperature."}, {"focus": ["hec", "pol", "ref"], "edges": [["hec", "pol"]], "text": "Loop 5, climate target: the price path is adjusted until the target is met. Read results as policy minus reference."}]}, "m3.1": {"title": "The GCAM pipeline, from data to findings", "caption": "Every result you publish sits at the end of this chain; each link is something you must record.", "nodes": [{"id": "src", "label": "Source data", "sub": "IEA, FAO, UC Davis, SSPs", "x": 110, "y": 100, "w": 170, "h": 62, "sys": "data", "detail": "Raw statistics and assumptions: energy balances, land and crop data, transport costs and intensities, population and GDP pathways."}, {"id": "gd", "label": "gcamdata", "sub": "R package, chunks", "x": 330, "y": 100, "w": 170, "h": 62, "sys": "data", "detail": "R code that turns source data into GCAM's input XML files, chunk by chunk. Systematic changes to assumptions belong here."}, {"id": "xml", "label": "Input XML", "sub": "one file per component", "x": 550, "y": 100, "w": 170, "h": 62, "sys": "data", "detail": "The files GCAM actually reads, such as transportation_UCD_CORE.xml. Since v8.5 transport uses billion pkm and 1975 dollars."}, {"id": "add", "label": "Your add-on XML", "sub": "loaded after the base files", "x": 550, "y": 250, "w": 170, "h": 62, "sys": "policy", "detail": "Small files that change selected inputs: a lower BEV cost, a new share-weight path, a carbon tax. Later files override earlier ones."}, {"id": "cfg", "label": "Configuration", "sub": "files, order, solver", "x": 780, "y": 175, "w": 170, "h": 62, "sys": "policy", "detail": "configuration.xml lists the ScenarioComponents in load order, the scenario name, the output database and the solver configuration."}, {"id": "core", "label": "GCAM core", "sub": "solves period by period", "x": 780, "y": 360, "w": 170, "h": 62, "sys": "neutral", "detail": "C++ model: in each 5-year period the solver adjusts prices until every market clears, then moves on. No foresight."}, {"id": "db", "label": "Output database", "sub": "XML database", "x": 550, "y": 440, "w": 170, "h": 62, "sys": "data", "detail": "Results are written to a BaseX XML database such as database_basexdb."}, {"id": "q", "label": "Queries", "sub": "rgcam, gcamreader", "x": 330, "y": 440, "w": 170, "h": 62, "sys": "data", "detail": "Saved queries pull tables out of the database into R (rgcam) or Python (gcamreader)."}, {"id": "an", "label": "Analysis", "sub": "your scripts", "x": 110, "y": 440, "w": 170, "h": 62, "sys": "neutral", "detail": "Tidy tables, differences from Reference, decompositions and figures: scripted, versioned and rerunnable."}], "edges": [{"from": "src", "to": "gd", "label": ""}, {"from": "gd", "to": "xml", "label": ""}, {"from": "xml", "to": "cfg", "label": "base files"}, {"from": "add", "to": "cfg", "label": "loaded last"}, {"from": "cfg", "to": "core", "label": ""}, {"from": "core", "to": "db", "label": ""}, {"from": "db", "to": "q", "label": ""}, {"from": "q", "to": "an", "label": ""}], "tour": [{"focus": ["src", "gd", "xml"], "edges": [["src", "gd"], ["gd", "xml"]], "text": "Source data become input XML through gcamdata. To change an assumption everywhere, change it here and rebuild."}, {"focus": ["add", "cfg"], "edges": [["add", "cfg"], ["xml", "cfg"]], "text": "For a scenario, add a small XML file and list it in the configuration after the base files. Later files override earlier ones."}, {"focus": ["cfg", "core"], "edges": [["cfg", "core"]], "text": "GCAM reads the configuration and solves each 5-year period for prices that clear every market."}, {"focus": ["core", "db", "q"], "edges": [["core", "db"], ["db", "q"]], "text": "Results go to a database; queries pull out exactly the tables you need."}, {"focus": ["q", "an"], "edges": [["q", "an"]], "text": "Your analysis scripts turn query tables into findings. Keep them under version control with everything upstream."}]}, "m3.2": {"title": "GCAM's passenger transport tree, with freight beside it", "caption": "Each level shares its parent's service by a logit; time cost enters at the mode level.", "nodes": [{"id": "pass", "label": "Passenger service", "sub": "trn_pass, billion pkm", "x": 450, "y": 60, "w": 200, "h": 62, "sys": "economy", "detail": "Total passenger-km demanded, driven by income (elasticity 1.0) and price (−1.25) in A54.demand.csv. Shared among modes by a relative-cost logit (exponent −2)."}, {"id": "walk", "label": "Walk and cycle", "sub": "time-heavy modes", "x": 110, "y": 190, "w": 170, "h": 62, "sys": "energy", "detail": "No money cost, but slow: the time-value multiplier 1.066 times the wage, over 4.8 or 15 km/h."}, {"id": "rail", "label": "Passenger rail", "sub": "electric, liquids", "x": 290, "y": 190, "w": 170, "h": 62, "sys": "energy", "detail": "Low money cost per pkm, multiplier 0.80, door-to-door speed around 42 km/h in the Middle East."}, {"id": "air", "label": "Domestic aviation", "sub": "fast, costly", "x": 470, "y": 190, "w": 170, "h": 62, "sys": "energy", "detail": "High money cost, multiplier 1.244 (includes waiting), speed about 197 km/h door to door."}, {"id": "road", "label": "Road", "sub": "trn_pass_road", "x": 680, "y": 190, "w": 170, "h": 62, "sys": "energy", "detail": "Buses and light vehicles share road passenger service (logit exponent −4)."}, {"id": "bus", "label": "Bus", "sub": "absolute logit −3", "x": 560, "y": 320, "w": 170, "h": 62, "sys": "energy", "detail": "Liquids, natural gas and battery-electric buses compete inside the Bus mode."}, {"id": "ldv", "label": "Light vehicles", "sub": "2W/3W and 4W", "x": 790, "y": 320, "w": 170, "h": 62, "sys": "energy", "detail": "trn_pass_road_LDV splits into two/three-wheelers and four-wheelers (exponent −4). Time value is added once, at the 4W node."}, {"id": "car", "label": "Car technologies", "sub": "liquids, hybrid, BEV, FCEV, NG", "x": 560, "y": 450, "w": 220, "h": 62, "sys": "energy", "detail": "Absolute-cost logit (exponent −8) on cost per pkm. BEV share-weight 0 until 2025, 1 from 2030; FCEV rises to 0.5 by 2050."}, {"id": "frt", "label": "Freight", "sub": "trn_freight, tkm", "x": 150, "y": 360, "w": 170, "h": 62, "sys": "economy", "detail": "Freight modes (road trucks by size, rail, domestic ship) compete on cost without a time term."}, {"id": "intl", "label": "International", "sub": "aviation and shipping", "x": 150, "y": 470, "w": 170, "h": 62, "sys": "climate", "detail": "International aviation and shipping draw on the same refined-liquids pool; there is no separate aviation fuel in the release."}], "edges": [{"from": "pass", "to": "walk", "label": ""}, {"from": "pass", "to": "rail", "label": ""}, {"from": "pass", "to": "air", "label": ""}, {"from": "pass", "to": "road", "label": ""}, {"from": "road", "to": "bus", "label": ""}, {"from": "road", "to": "ldv", "label": ""}, {"from": "ldv", "to": "car", "label": "4W"}, {"from": "frt", "to": "intl", "label": "same fuel pool", "sys": "climate"}], "tour": [{"focus": ["pass"], "edges": [], "text": "Start from passenger service: billion passenger-km, growing with income and falling with price."}, {"focus": ["pass", "walk", "rail", "air", "road"], "edges": [["pass", "walk"], ["pass", "rail"], ["pass", "air"], ["pass", "road"]], "text": "Modes share the service by a relative-cost logit on generalised cost: money plus time."}, {"focus": ["road", "bus", "ldv"], "edges": [["road", "bus"], ["road", "ldv"]], "text": "Road splits into buses and light vehicles; light vehicles into two/three-wheelers and four-wheelers."}, {"focus": ["ldv", "car"], "edges": [["ldv", "car"]], "text": "At the bottom, car technologies compete by an absolute-cost logit on cost per passenger-km."}, {"focus": ["frt", "intl"], "edges": [["frt", "intl"]], "text": "Freight is a parallel tree measured in tonne-km, with no time term. International aviation and shipping use the general liquids pool."}]}, "m3.3": {"title": "The GCAM transport literature in four strands", "caption": "Every strand feeds the synthesis; your question should start from its gaps.", "nodes": [{"id": "core", "label": "GCAM transport literature", "sub": "2011–2026", "x": 450, "y": 260, "w": 220, "h": 62, "sys": "neutral", "detail": "About 33 peer-reviewed studies and grey literature collected for this course; DOIs checked where possible."}, {"id": "a", "label": "Foundations", "sub": "how the sector was built", "x": 150, "y": 90, "w": 170, "h": 62, "sys": "energy", "detail": "UC Davis database, Kyle and Kim (2011) on light-duty vehicles, GCAM model descriptions and gcamdata."}, {"id": "b", "label": "Model comparisons", "sub": "why IAMs disagree", "x": 750, "y": 90, "w": 170, "h": 62, "sys": "economy", "detail": "Edelenbosch et al. (2017) and related studies: decomposing passenger futures across IAMs; behaviour and demand assumptions dominate."}, {"id": "c", "label": "Applications", "sub": "modes, fuels, countries", "x": 150, "y": 430, "w": 170, "h": 62, "sys": "climate", "detail": "Electric vehicles, hydrogen, biojet fuels for aviation, freight, zero-emission transport (Speizer et al., 2024), USA, China, India."}, {"id": "d", "label": "Saudi Arabia, downscaling", "sub": "GCAM-KSA, DSCALE", "x": 750, "y": 430, "w": 170, "h": 62, "sys": "policy", "detail": "GCAM-KSA papers (2024–2025), KAPSARC transport studies with 2060 results, and DSCALE (Sferra et al., 2026)."}, {"id": "syn", "label": "Synthesis", "sub": "known, disputed, unknown", "x": 450, "y": 90, "w": 170, "h": 62, "sys": "data", "detail": "Agreed: electrification dominates light-duty decarbonisation. Disputed: speed of uptake, role of hydrogen and biofuels. Unknown: behaviour, freight and aviation fuels at scale."}], "edges": [{"from": "a", "to": "core", "label": ""}, {"from": "b", "to": "core", "label": ""}, {"from": "c", "to": "core", "label": ""}, {"from": "d", "to": "core", "label": ""}, {"from": "core", "to": "syn", "label": "what it adds up to"}], "tour": [{"focus": ["a", "core"], "edges": [["a", "core"]], "text": "Start with the foundations: how GCAM's transport sector and data were built."}, {"focus": ["b", "core"], "edges": [["b", "core"]], "text": "Model comparisons show why IAMs disagree: assumptions about behaviour, cost and demand."}, {"focus": ["c", "core"], "edges": [["c", "core"]], "text": "Applications test technologies, fuels and policies by mode and by country."}, {"focus": ["d", "core"], "edges": [["d", "core"]], "text": "Saudi Arabia and downscaling: GCAM-KSA and methods to reach country level."}, {"focus": ["core", "syn"], "edges": [["core", "syn"]], "text": "Read the synthesis last: the gaps there are where new research is needed."}]}, "m3.4": {"title": "The study design cycle", "caption": "Each box is a decision you write down before running GCAM; validity feeds back into the question.", "nodes": [{"id": "q", "label": "Question", "sub": "decision, metric, comparison", "x": 450, "y": 60, "w": 200, "h": 62, "sys": "policy", "detail": "A topic becomes a question when it names a decision, a metric (for example 2050 transport CO2) and a comparison (against Reference or another policy)."}, {"id": "ref", "label": "Reference", "sub": "today's policies", "x": 760, "y": 170, "w": 170, "h": 62, "sys": "economy", "detail": "The counterfactual world: a stated SSP, current policies, default technology assumptions. Report it in full."}, {"id": "lev", "label": "Levers", "sub": "one change at a time", "x": 760, "y": 350, "w": 170, "h": 62, "sys": "energy", "detail": "Vehicle costs, load factors, share-weight paths, value of time, fuel prices: each changed alone first."}, {"id": "pol", "label": "Policies", "sub": "price or quantity", "x": 450, "y": 460, "w": 170, "h": 62, "sys": "policy", "detail": "A carbon price (model finds emissions) or a constraint (model finds the price); standards as credit markets."}, {"id": "unc", "label": "Uncertainty plan", "sub": "ranges, ensemble", "x": 140, "y": 350, "w": 170, "h": 62, "sys": "data", "detail": "Choose uncertain inputs, ranges and method: one-at-a-time sensitivity, a factorial matrix, or an ensemble with scenario discovery."}, {"id": "val", "label": "Validity", "sub": "why believe it?", "x": 140, "y": 170, "w": 170, "h": 62, "sys": "neutral", "detail": "Calibration, hindcast against recent history, and benchmarking against other models and the AR6 database."}], "edges": [{"from": "q", "to": "ref", "label": ""}, {"from": "ref", "to": "lev", "label": ""}, {"from": "lev", "to": "pol", "label": ""}, {"from": "pol", "to": "unc", "label": ""}, {"from": "unc", "to": "val", "label": ""}, {"from": "val", "to": "q", "label": "refine"}], "tour": [{"focus": ["q"], "edges": [], "text": "Start with a question that names a decision, a metric and a comparison."}, {"focus": ["ref", "lev"], "edges": [["q", "ref"], ["ref", "lev"]], "text": "Define the Reference, then change one lever at a time."}, {"focus": ["pol"], "edges": [["lev", "pol"]], "text": "Add policies as a price or a quantity, depending on what your question asks."}, {"focus": ["unc"], "edges": [["pol", "unc"]], "text": "Plan the uncertainty analysis before running: inputs, ranges and method."}, {"focus": ["val", "q"], "edges": [["unc", "val"], ["val", "q"]], "text": "Argue validity, and refine the question if the design cannot answer it."}]}, "m3.5": {"title": "How add-on files layer onto the base inputs", "caption": "Base files load first; add-ons and policies override them; the batch file runs every combination.", "nodes": [{"id": "base", "label": "Base input XML", "sub": "transportation_UCD_CORE.xml", "x": 140, "y": 90, "w": 200, "h": 62, "sys": "data", "detail": "GCAM's standard transport inputs, built by gcamdata. Never edit them by hand."}, {"id": "cost", "label": "Cost add-on", "sub": "trn_bev_cost_low.xml", "x": 140, "y": 220, "w": 200, "h": 62, "sys": "energy", "detail": "Lowers the BEV input-cost from 2030. Values must match the base file's units (billion pkm, 1975$ since v8.5)."}, {"id": "sw", "label": "Share-weight add-on", "sub": "trn_zev_shareweights.xml", "x": 140, "y": 350, "w": 200, "h": 62, "sys": "energy", "detail": "Sets share-weight values and an interpolation rule so new technologies enter on your schedule."}, {"id": "lf", "label": "Service add-on", "sub": "trn_loadfactor_up.xml", "x": 140, "y": 470, "w": 200, "h": 62, "sys": "energy", "detail": "Raises car load factors: more people per car means lower cost and energy per pkm."}, {"id": "cfg", "label": "Configuration", "sub": "ScenarioComponents in order", "x": 470, "y": 280, "w": 200, "h": 62, "sys": "neutral", "detail": "Lists base files first and add-ons after. Later files override earlier ones."}, {"id": "pol", "label": "Policy files", "sub": "tax, constraint, ZEV credits", "x": 470, "y": 460, "w": 200, "h": 62, "sys": "policy", "detail": "policy_carbon_tax.xml, policy_co2_constraint_netzero.xml and policy_zev_standard.xml."}, {"id": "batch", "label": "Batch file", "sub": "batch_transport.xml", "x": 770, "y": 280, "w": 170, "h": 62, "sys": "data", "detail": "Crosses component sets into a scenario matrix: Reference, BEV-low, LF-up, Carbon-tax, NetZero and combinations."}, {"id": "run", "label": "GCAM runs", "sub": "one database", "x": 770, "y": 450, "w": 170, "h": 62, "sys": "neutral", "detail": "All scenarios write to one output database for side-by-side queries."}], "edges": [{"from": "base", "to": "cfg", "label": "first"}, {"from": "cost", "to": "cfg", "label": ""}, {"from": "sw", "to": "cfg", "label": ""}, {"from": "lf", "to": "cfg", "label": ""}, {"from": "pol", "to": "cfg", "label": "last"}, {"from": "cfg", "to": "batch", "label": ""}, {"from": "batch", "to": "run", "label": ""}], "tour": [{"focus": ["base", "cfg"], "edges": [["base", "cfg"]], "text": "Base files load first and stay untouched."}, {"focus": ["cost", "sw", "lf", "cfg"], "edges": [["cost", "cfg"], ["sw", "cfg"], ["lf", "cfg"]], "text": "Each lever is a small add-on that repeats the nesting down to one value."}, {"focus": ["pol", "cfg"], "edges": [["pol", "cfg"]], "text": "Policies load last: a tax, a constraint, or a credit market for zero-emission vehicles."}, {"focus": ["batch", "run"], "edges": [["cfg", "batch"], ["batch", "run"]], "text": "A batch file runs every combination into one database."}]}, "m3.6": {"title": "From database to defensible findings", "caption": "Top row gets clean numbers; second row tests them; only what survives both reaches the findings.", "nodes": [{"id": "db", "label": "Output database", "sub": "all scenarios", "x": 110, "y": 90, "w": 170, "h": 62, "sys": "data", "detail": "One database holding Reference and every policy and sensitivity run."}, {"id": "q", "label": "Saved queries", "sub": "transport_queries.xml", "x": 330, "y": 90, "w": 170, "h": 62, "sys": "data", "detail": "Service output by mode, final energy by fuel, CO2 by sector: the same queries every time."}, {"id": "tidy", "label": "Tidy tables", "sub": "one row per value", "x": 550, "y": 90, "w": 170, "h": 62, "sys": "data", "detail": "Scenario, region, sector, mode, fuel, year, value, unit: ready for any analysis."}, {"id": "diff", "label": "Policy minus Reference", "sub": "the effect", "x": 770, "y": 90, "w": 170, "h": 62, "sys": "policy", "detail": "Every reported result is a difference from Reference, explained."}, {"id": "lmdi", "label": "Decomposition", "sub": "activity, structure…", "x": 770, "y": 270, "w": 170, "h": 62, "sys": "energy", "detail": "LMDI splits the CO2 change into activity, structure, intensity and carbon effects that add up exactly."}, {"id": "tor", "label": "Sensitivity", "sub": "tornado chart", "x": 550, "y": 270, "w": 170, "h": 62, "sys": "economy", "detail": "Vary one input at a time between low and high values to rank what matters."}, {"id": "sd", "label": "Scenario discovery", "sub": "ensemble + rules", "x": 330, "y": 270, "w": 170, "h": 62, "sys": "economy", "detail": "Search an ensemble for the input ranges that explain high-emission outcomes (coverage and density)."}, {"id": "bm", "label": "Benchmark", "sub": "AR6, other models", "x": 110, "y": 270, "w": 170, "h": 62, "sys": "climate", "detail": "Compare with AR6 scenarios with similar carbon prices or warming, and explain differences."}, {"id": "find", "label": "Defensible findings", "sub": "what survives the tests", "x": 450, "y": 450, "w": 220, "h": 62, "sys": "neutral", "detail": "Findings that hold across sensitivities, are explained by decomposition and sit sensibly against other models."}], "edges": [{"from": "db", "to": "q", "label": ""}, {"from": "q", "to": "tidy", "label": ""}, {"from": "tidy", "to": "diff", "label": ""}, {"from": "diff", "to": "lmdi", "label": ""}, {"from": "lmdi", "to": "find", "label": ""}, {"from": "tor", "to": "find", "label": ""}, {"from": "sd", "to": "find", "label": ""}, {"from": "bm", "to": "find", "label": ""}], "tour": [{"focus": ["db", "q", "tidy"], "edges": [["db", "q"], ["q", "tidy"]], "text": "Extract results with saved queries into tidy tables, the same way every time."}, {"focus": ["tidy", "diff"], "edges": [["tidy", "diff"]], "text": "Report each policy as its difference from Reference."}, {"focus": ["diff", "lmdi"], "edges": [["diff", "lmdi"]], "text": "Decompose the change to explain it: activity, structure, intensity, carbon."}, {"focus": ["tor", "sd"], "edges": [], "text": "Stress-test: rank single assumptions, then search an ensemble for what drives bad outcomes."}, {"focus": ["bm", "find"], "edges": [["bm", "find"], ["lmdi", "find"], ["tor", "find"], ["sd", "find"]], "text": "Benchmark against other models; keep only findings that survive."}]}, "m3.7": {"title": "Going finer (top) and wider (bottom)", "caption": "Top row: a region's results shared among its countries. Bottom: GCAM linked with a stock model and a national model.", "nodes": [{"id": "reg", "label": "Middle East region", "sub": "GCAM results", "x": 140, "y": 100, "w": 170, "h": 62, "sys": "economy", "detail": "Public GCAM releases group Saudi Arabia with its neighbours in one region."}, {"id": "ds", "label": "Downscaling", "sub": "proportional or convergence", "x": 450, "y": 100, "w": 200, "h": 62, "sys": "data", "detail": "Share regional results among countries: keep today's shares, or converge intensities towards the regional average (DSCALE-style), then harmonise to the regional total."}, {"id": "cty", "label": "Countries", "sub": "add up to the region", "x": 760, "y": 100, "w": 170, "h": 62, "sys": "economy", "detail": "Country pathways that still sum to the regional result in every year."}, {"id": "ksa", "label": "GCAM-KSA", "sub": "Saudi Arabia as its own region", "x": 140, "y": 280, "w": 190, "h": 62, "sys": "policy", "detail": "Built on GCAM 6.0 by KAPSARC with PNNL: Saudi Arabia split from the Middle East, data split and recalibrated."}, {"id": "g", "label": "GCAM transport", "sub": "sales, service, prices", "x": 450, "y": 300, "w": 170, "h": 62, "sys": "energy", "detail": "GCAM reports service, energy and new-vehicle choices; it does not track the vehicle stock."}, {"id": "stock", "label": "Vehicle stock model", "sub": "fleets, retirements", "x": 760, "y": 280, "w": 170, "h": 62, "sys": "energy", "detail": "Turns sales shares into fleets with survival curves, so 'cars on the road' can be reported."}, {"id": "leap", "label": "LEAP national model", "sub": "detailed national system", "x": 760, "y": 440, "w": 170, "h": 62, "sys": "policy", "detail": "Takes GCAM prices and demands as drivers; can return national detail for the next iteration."}, {"id": "loop", "label": "Convergence", "sub": "iterate until they agree", "x": 450, "y": 450, "w": 170, "h": 62, "sys": "neutral", "detail": "Decide which variables pass each way and iterate until the models agree within a tolerance."}], "edges": [{"from": "reg", "to": "ds", "label": ""}, {"from": "ds", "to": "cty", "label": ""}, {"from": "g", "to": "stock", "label": "sales shares"}, {"from": "stock", "to": "leap", "label": "fleet"}, {"from": "leap", "to": "loop", "label": ""}, {"from": "loop", "to": "g", "label": "update"}], "tour": [{"focus": ["reg", "ds", "cty"], "edges": [["reg", "ds"], ["ds", "cty"]], "text": "Finer, option 1: downscale regional results to countries, keeping the regional total."}, {"focus": ["ksa"], "edges": [], "text": "Finer, option 2: model the country as its own region, as GCAM-KSA does for Saudi Arabia."}, {"focus": ["g", "stock"], "edges": [["g", "stock"]], "text": "GCAM chooses new vehicles; a stock model turns sales into fleets."}, {"focus": ["stock", "leap", "loop", "g"], "edges": [["stock", "leap"], ["leap", "loop"], ["loop", "g"]], "text": "Wider: soft-link with a national model and iterate until the models agree."}]}, "m3.8": {"title": "Around your study: limits, ethics and reporting", "caption": "A finished study states its limits and choices, and ships everything needed to rebuild it.", "nodes": [{"id": "study", "label": "Your study", "sub": "question, runs, findings", "x": 450, "y": 270, "w": 200, "h": 62, "sys": "neutral", "detail": "The scenarios, results and claims you want others to trust."}, {"id": "lim", "label": "What GCAM can't see", "sub": "fleets, behaviour, fuels", "x": 150, "y": 110, "w": 190, "h": 62, "sys": "energy", "detail": "No vehicle stock, limited behaviour, one liquids pool for aviation and shipping, no explicit charging infrastructure."}, {"id": "eth", "label": "Ethics", "sub": "whose future, whose cost", "x": 750, "y": 110, "w": 170, "h": 62, "sys": "economy", "detail": "Who travels more, who pays, reliance on future carbon removal, and the SSP world you assumed."}, {"id": "peer", "label": "Peer review", "sub": "can others check it?", "x": 450, "y": 90, "w": 170, "h": 62, "sys": "policy", "detail": "Reviewers need the version, the changes and the package to judge your claims."}, {"id": "guide", "label": "Describing GCAM", "sub": "community guidelines", "x": 150, "y": 430, "w": 190, "h": 62, "sys": "policy", "detail": "State the version, all changes to inputs and code, and where they are archived, following JGCRI's guidelines."}, {"id": "iamc", "label": "IAMC reporting", "sub": "standard variables", "x": 750, "y": 430, "w": 170, "h": 62, "sys": "data", "detail": "Report with standard IAMC variable names (for example Final Energy|Transportation) so results compare with other models."}, {"id": "pkg", "label": "Reproducible package", "sub": "files, scripts, readme", "x": 450, "y": 450, "w": 170, "h": 62, "sys": "data", "detail": "GCAM version, add-ons, configuration and batch files, queries, analysis scripts and a readme in one archive."}], "edges": [{"from": "lim", "to": "study", "label": "state limits"}, {"from": "eth", "to": "study", "label": "make choices visible"}, {"from": "study", "to": "guide", "label": ""}, {"from": "study", "to": "iamc", "label": ""}, {"from": "study", "to": "pkg", "label": ""}, {"from": "pkg", "to": "peer", "label": "lets others check", "sys": "data"}], "tour": [{"focus": ["lim", "study"], "edges": [["lim", "study"]], "text": "Name what GCAM transport cannot see, and how each limit could bias your result."}, {"focus": ["eth", "study"], "edges": [["eth", "study"]], "text": "Make ethical choices visible: who travels, who pays, and reliance on future removals."}, {"focus": ["study", "guide", "iamc"], "edges": [["study", "guide"], ["study", "iamc"]], "text": "Describe GCAM properly and report in standard IAMC variables."}, {"focus": ["pkg", "peer"], "edges": [["study", "pkg"], ["pkg", "peer"]], "text": "Ship a package that rebuilds every figure, so others can check your claims."}]}};
